<script>
(()=>{const devices=<?=json_encode($scInverters,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,config=<?=json_encode($scConfig,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,selectedDevice=<?=json_encode($scSelected)?>,device=document.getElementById('scDevice'),rows=document.getElementById('scRows'),empty=document.getElementById('scEmpty');let available=[];const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));if(selectedDevice)device.value=selectedDevice;
function selected(){return [...rows.querySelectorAll('.sc-param-toggle.is-selected')].map(button=>button.dataset.value)}function sync(){const used=new Set(selected());rows.querySelectorAll('.sc-param-toggle').forEach(button=>{button.disabled=!button.classList.contains('is-selected')&&used.has(button.dataset.value);button.setAttribute('aria-pressed',button.classList.contains('is-selected')?'true':'false')});empty.hidden=rows.children.length>0;document.getElementById('scAdd').disabled=available.length>0&&used.size>=available.length}function add(row={}){const div=document.createElement('div'),chosen=new Set(Array.isArray(row.parameters)?row.parameters:[row.parameter].filter(Boolean));div.className='sc-row';div.innerHTML='<div class="sc-row-head"><input type="text" maxlength="60" placeholder="Channel name" value="'+esc(row.channel||'')+'"><button class="sc-remove-channel" type="button" title="ลบ Channel"><i class="fa-solid fa-trash"></i></button></div><div class="sc-select-actions"><button class="sc-check-all" type="button"><i class="fa-solid fa-check-double"></i> Check all</button><button class="sc-uncheck-all" type="button"><i class="fa-solid fa-xmark"></i> Uncheck all</button></div><div class="sc-param-list">'+available.map(p=>'<button type="button" class="sc-param-toggle'+(chosen.has(p)?' is-selected':'')+'" data-value="'+esc(p)+'" aria-pressed="'+(chosen.has(p)?'true':'false')+'"><i class="fa-solid fa-check"></i><span>'+esc(p)+'</span></button>').join('')+'</div>';rows.appendChild(div);div.querySelectorAll('.sc-param-toggle').forEach(button=>button.onclick=()=>{if(button.disabled)return;button.classList.toggle('is-selected');sync()});div.querySelector('.sc-check-all').onclick=()=>{div.querySelectorAll('.sc-param-toggle:not(:disabled)').forEach(button=>button.classList.add('is-selected'));sync()};div.querySelector('.sc-uncheck-all').onclick=()=>{div.querySelectorAll('.sc-param-toggle.is-selected').forEach(button=>button.classList.remove('is-selected'));sync()};div.querySelector('.sc-remove-channel').onclick=()=>{div.remove();sync()};sync()}
function load(){const id=device.value,d=devices[id]||{};document.getElementById('scModel').textContent=(d.model||'')+' · '+id;fetch('./api_mdbiotx.php',{cache:'no-store'}).then(r=>r.json()).then(p=>{available=Object.keys((p.data||{})[id]||{}).filter(k=>/^in_dca_\d+$/i.test(k)).sort((a,b)=>Number(a.match(/\d+/))-Number(b.match(/\d+/)));rows.innerHTML='';(config[id]||[]).forEach(add);sync()})}device.onchange=load;document.getElementById('scAdd').onclick=()=>add();document.getElementById('scSave').onclick=()=>{config[device.value]=[...rows.children].map(row=>({channel:row.querySelector('input[type="text"]').value.trim(),parameters:[...row.querySelectorAll('.sc-param-toggle.is-selected')].map(button=>button.dataset.value)})).filter(row=>row.parameters.length);fetch('./solar_performance_config_api.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'dataE='+encodeURIComponent(JSON.stringify(config))}).then(async r=>{const d=await r.json();if(!r.ok||d.error)throw Error(d.error||'Save failed');Object.assign(config,d);if(window.Swal)Swal.fire({icon:'success',title:'บันทึก Channel Config แล้ว',timer:1300,showConfirmButton:false});else alert('Saved')}).catch(e=>window.Swal?Swal.fire('บันทึกไม่สำเร็จ',e.message,'error'):alert(e.message))};load()})();
</script>
<script>
(()=>{const rows=document.getElementById('scRows');if(!rows)return;const fillChannelNames=()=>{[...rows.querySelectorAll('.sc-row')].forEach((row,index)=>{const input=row.querySelector('input[type="text"]');if(input&&!input.value.trim())input.value='Channel '+(index+1)})};new MutationObserver(fillChannelNames).observe(rows,{childList:true});fillChannelNames()})();
</script>
<script>
(()=>{const add=document.getElementById('scAdd'),save=document.getElementById('scSave'),quickAdd=document.getElementById('scQuickAdd'),quickSave=document.getElementById('scQuickSave');if(!add||!save||!quickAdd||!quickSave)return;quickAdd.onclick=()=>add.click();quickSave.onclick=()=>save.click();new MutationObserver(()=>quickAdd.disabled=add.disabled).observe(add,{attributes:true,attributeFilter:['disabled']});quickAdd.disabled=add.disabled})();
</script>
